class Invoice {
  total = this.net + this.tax;
  net = 100;
  tax = this.net * 0.2;
  gross = this.net + this.tax;

  constructor(net) {
    this.net = net;
  }
}

const invoice = new Invoice(50);

console.log(invoice.total);
console.log(invoice.tax);
console.log(invoice.gross);
console.log(invoice.net);
